package main

import (
	"fmt"
)

// ۱. سطوح نقش‌های کاربری با استفاده از iota
const (
	RoleGuest = iota // 0
	RoleUser         // 1
	RoleAdmin        // 2
	RoleSuperAdmin   // 3
)

// ۲. پرچم‌های بیتی دسترسی (Bitmask Permissions) با 1 << iota
const (
	PermissionRead   = 1 << iota // 1 (1 << 0)
	PermissionWrite              // 2 (1 << 1)
	PermissionDelete             // 4 (1 << 2)
)

// ۳. محاسبه سهمیه بر اساس مگابایت با تبدیل صریح نوع
func CalculateQuotaMB(gigabytes float64) int {
	megabytes := gigabytes * 1024.0
	return int(megabytes)
}

func main() {
	// ۴. نمایش مقادیر صفر (Zero Values) در متغیرهای سرور
	var serverPort int
	var serverHost string
	var isTLS bool

	fmt.Println("--- تنظیمات پیش‌فرض سرور (Zero Values) ---")
	fmt.Printf("Port: %d, Host: '%s', TLS: %t\n", serverPort, serverHost, isTLS)

	// مقداردهی با تعریف کوتاه (Short Variable Declaration)
	serverPort = 8443
	serverHost = "api.internal.local"
	isTLS = true

	fmt.Println("\n--- تنظیمات فعال سرور ---")
	fmt.Printf("Endpoint: https://%s:%d (TLS Active: %t)\n", serverHost, serverPort, isTLS)

	// ۵. تست نقش‌ها و پرچم‌های iota
	currentRole := RoleAdmin
	userPerms := PermissionRead | PermissionWrite

	fmt.Println("\n--- وضعیت دسترسی و نقش‌ها ---")
	fmt.Printf("Current Role Code: %d (Admin: %t)\n", currentRole, currentRole == RoleAdmin)
	fmt.Printf("Bitmask Permissions: %d (Has Read: %t, Has Write: %t)\n",
		userPerms,
		(userPerms&PermissionRead) != 0,
		(userPerms&PermissionWrite) != 0,
	)

	// ۶. تست تابع تبدیل نوع
	quotaGB := 2.5
	quotaMB := CalculateQuotaMB(quotaGB)
	fmt.Printf("\n--- سهمیه دیسک ---\n%.2f GB معادل %d MB است.\n", quotaGB, quotaMB)
}
